package com.backend.gapfinder.view.dto.requests;

import lombok.Data;

// Body of POST /chats/messages (the sender is the authenticated user)
@Data
public class ChatMessageRequest {

    // Id of the friend who receives the message
    private Long receiverId;

    // Text of the message (not blank, max 500)
    private String content;

    // Id generated by the app (UUID) so a retried message is not duplicated
    private String clientId;
}
